export const normalizeTeamName = (value) => String(value || "")
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase()
  .replace(/&/g, " and ")
  .replace(/[^a-z0-9]+/g, "_")
  .replace(/^_+|_+$/g, "");

export const getLogo = (teamName) => {
  const slug = normalizeTeamName(teamName);
  if (!slug) return null;
  const direct = FILE_LOGOS[slug];
  if (direct) return direct;
  const alias = ALIASES[slug];
  if (alias && FILE_LOGOS[alias]) return FILE_LOGOS[alias];

  // Try common club-name variations without ever inventing a file URL.
  const variants = [
    slug.replace(/^(fc|afc|acf|ss|ssc|as|us|ud|rcd|rc|cd|sl|sv|vfl|vfb|rsc|kaa|krc|kv|kvc|sc|k)_/, ""),
    slug.replace(/_(fc|cf|bc|ac|sc|sk|jk|fk|cfc|calcio|va|ksv|kv|sad)$/, ""),
    slug.replace(/^(fc|afc|acf|ss|ssc|as|us|ud|rcd|rc|cd|sl|sv|vfl|vfb|rsc|kaa|krc|kv|kvc|sc|k)_/, "").replace(/_(fc|cf|bc|ac|sc|sk|jk|fk|cfc|calcio|va|ksv|kv|sad)$/, "")
  ];
  for (const variant of variants) {
    if (FILE_LOGOS[variant]) return FILE_LOGOS[variant];
    if (ALIASES[variant] && FILE_LOGOS[ALIASES[variant]]) return FILE_LOGOS[ALIASES[variant]];
  }
  return null;
};
export default getLogo;
